# -*- coding: utf-8 -*-
# Сверка с ответами учебника Макарычев 9, часть 4 (расхождения 200–267): пересчитано вручную + SymPy (check_mk4.py), условия сверены со сканом.
KB = "ключ неверен (сверка с ответом учебника Макарычев 9 и пересчёт вручную): "
SRC = "сверка с ответами учебника Макарычев 9 (углублённый) 25.09 + пересчёт вручную"
P = {}
def K(t, k, note, **kw):
    P[t] = {"k": k, "why": KB + note, "src": SRC}; P[t].update(kw)
OLD = lambda v, n: [(v, "прежний (неверный) ключ: " + n)]
K("G9_TB_ДГ5_677_4", r"$x_{1} = 2\sqrt{3}$, $n = 5$", "Sₙ = (xₙq − x₁)/(q − 1) ⇒ 54 − x₁ = (26√3 + 24)(√3 − 1) = 54 − 2√3 ⇒ x₁ = 2√3; 2√3·(√3)ⁿ⁻¹ = 18√3 ⇒ n = 5 (было x₁ = 6, n = 4)")
K("G9_TB_УПК_789_2", r"$\dfrac{\sqrt{3}}{3}$ или $-\dfrac{\sqrt{3}}{3}$", "q⁸ = 2/162 = 1/81 ⇒ q = ±1/√3 (было ±1/3: (1/3)⁸ = 1/6561)")
K("G9_TB_ЗПТ_847", r"$x_{1} = \dfrac{3-\sqrt{5}}{4}$, $x_{2} = \dfrac{3+\sqrt{5}}{4}$; $x_{1} = \dfrac{-3-\sqrt{5}}{4}$, $x_{2} = \dfrac{-3+\sqrt{5}}{4}$",
  "x₁² + x₂² = 9a² − 2a² = 7a² = 1,75 ⇒ a = ±0,5 ⇒ x² ∓ 1,5x + 0,25 = 0 (было 0,5 и 1: 0,25 + 1 ≠ 1,75)")
K("G9_TB_ЗПТ_853", r"$(0; 0)$, $(\sqrt{7}; \sqrt{7})$, $(-\sqrt{7}; -\sqrt{7})$, $(\sqrt{19}; -\sqrt{19})$, $(-\sqrt{19}; \sqrt{19})$, $(2; 3)$, $(3; 2)$, $(-2; -3)$, $(-3; -2)$",
  "x = y ⇒ 2x³ = 14x; x = −y ⇒ 2x³ = 38x; иначе x² + xy + y² = 19, x² − xy + y² = 7 ⇒ xy = 6, x² + y² = 13 (в ключе были не решения (√3; −√3), (√19; 0), (0; √7) и потеряны (2; 3) и др.)")
K("G9_TB_14_237_1", r"$a = 1{,}5$", "(a + 1)² + (a − 4)(a − 2) = 3a + 3 ⇒ 2a² − 7a + 6 = 0 ⇒ a = 2 (вне ОДЗ) или 1,5 (было 0; 2,5)")
K("G9_TB_14_241_1", r"$a = -1{,}4$; $a = -0{,}5$; $a = 0{,}5$", "20a³ + 28a² − 5a − 7 = (5a + 7)(4a² − 1) = 0 (было 0,5; −0,7)")
K("G9_TB_15_245_б", r"$\dfrac{1}{3}$; $3$; $\dfrac{-3-\sqrt{5}}{2}$; $\dfrac{-3+\sqrt{5}}{2}$", "t = x + 1/x: t² − t/3 − 10 = 0 ⇒ t = 10/3 или −3; ключ был записан десятичными приближениями, заменён точными значениями")
K("G9_TB_8_101_2", r"нулей нет", "(2x + 3)/(9 − 4x²) = 1/(3 − 2x) при x ≠ ±1,5 — не обращается в нуль; при x = −1,5 знаменатель равен 0 (было x = −1,5)")
K("G9_TB_ЗПТ_851", r"$(6; -1)$, $(13; -15)$", "деление уравнений: y = 11 − 2x ⇒ (11 − x)(8 − x) = 10 ⇒ x = 6 или 13 (было (3; 2), (6; −1): (3; 2) не решение)")
K("G9_TB_ДГ5_654_3", r"$a_{1} = 0{,}5$, $n = 100$ или $a_{1} = 0$, $n = 101$", "a₁ = 50 − (n − 1)/2, n(201 − n)/4 = 2525 ⇒ n = 100 или 101 (было a₁ = 1, n = 99: S₉₉ = 2524,5)")
K("G9_TB_ЗПТ_852_1", r"$(10; 7)$, $(-7; -10)$", "d = x − y, P = xy: d³ + 2·210 = 447 ⇒ d = 3, P = 70 (было (7; 3), (−3; −7): x − y = 4)")
K("G9_TB_14_228_2", r"$x = 1$; $x = -\sqrt{3}$; $x = \sqrt{3}$", "(x − 1)(x² − 3)(x² + 1) = 0 (было ±√2)", dadd=OLD(r"$x = 1; x = -\sqrt{2}; x = \sqrt{2}$", "неверное разложение"))
K("G9_TB_14_229_2", r"$u = -2$; $u = 1$; $u = 2$", "(u − 1)(u⁶ − 64) = 0 ⇒ u = 1, ±2 (в ключе не было −2 и были комплексные числа); вариант «1; 2; −2» равен ответу — закрыт",
  drop=[1], dadd=OLD(r"$1; 2; -1 + i\sqrt{3}; -1 - i\sqrt{3}$", "потерян корень −2"))
K("G9_TB_20_386_2", r"$(4; -7)$, $(-2; -13)$", "x = y + 11 ⇒ (y + 10)² = 9 ⇒ y = −7 или −13 (было (10; −1), (2; −9))", dadd=OLD(r"$(10;-1), (2;-9)$", "не решения системы"))
K("G9_TB_20_387_1", r"$(-5; 4)$, $\left(-\dfrac{7}{3}; \dfrac{36}{5}\right)$", "y = (6x + 50)/5 ⇒ 3x² + 22x + 35 = 0 ⇒ x = −5 или −7/3 (было (−4; 4), (5; −6))")
